def design(d, t, kind):
    r = d[:, 0] / 7.5 - 1
    c = d[:, 2] / 11.5 - 1
    e = np.exp(-d / t)
    nearest = np.max(e, axis=1)
    s = e.sum(axis=1)
    cols = [np.ones(len(d)), r, c]
    if kind == 'constant':
        return np.ones((len(d), 1))
    if kind == 'nearest':
        cols += [nearest]
    if kind == 'sum':
        cols += [s]
    if kind == 'union':
        cols += [s, (e[:, 0] + e[:, 1]) * (e[:, 2] + e[:, 3])]
    if kind == 'axes':
        cols += [e[:, 0] + e[:, 1], e[:, 2] + e[:, 3]]
    if kind == 'mixed':
        cols += [nearest, s - nearest]
    return np.column_stack(cols)
